const __raw = $input.item.json.body || {};
const body = { ...__raw };
for (const __k in __raw) { const __v = __raw[__k]; if (__v && typeof __v === 'object' && !Array.isArray(__v)) Object.assign(body, __v); }
let targetDate = (body.date || '').trim();

// If no date is passed, default to tomorrow
if (!targetDate) {
  const now = new Date();
  now.setDate(now.getDate() + 1);
  targetDate = now.toISOString().split('T')[0];
}

const tz = body.timezone || $env.BUSINESS_TIMEZONE || 'America/New_York';

// Business hours: 09:00 to 17:00
// Fetch the whole day (UTC) so events in any timezone are captured.
const timeMin = `${targetDate}T00:00:00Z`;
const timeMax = `${targetDate}T23:59:59Z`;

return {
  json: {
    targetDate,
    timezone: tz,
    timeMin,
    timeMax
  }
};

const dateInfo = $('Parse Target Date').first().json;
const events = $input.all();
const targetDate = dateInfo.targetDate;
const tz = dateInfo.timezone || $env.BUSINESS_TIMEZONE || 'America/New_York';
const [Y, Mo, D] = targetDate.split('-').map(x => parseInt(x, 10));
const pad = n => String(n).padStart(2, '0');

// DST-aware offset (e.g. "-04:00") for a wall time in the target IANA zone.
function offsetStr(y, mo, d, h, mi, timeZone) {
  const wallAsUTC = Date.UTC(y, mo - 1, d, h, mi, 0);
  const dtf = new Intl.DateTimeFormat('en-US', { timeZone, hour12: false, year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', second: '2-digit' });
  const p = dtf.formatToParts(new Date(wallAsUTC)).reduce((a, x) => { a[x.type] = x.value; return a; }, {});
  let hh = parseInt(p.hour, 10); if (hh === 24) hh = 0;
  const tzAsUTC = Date.UTC(parseInt(p.year, 10), parseInt(p.month, 10) - 1, parseInt(p.day, 10), hh, parseInt(p.minute, 10), parseInt(p.second, 10));
  const offMin = Math.round((tzAsUTC - wallAsUTC) / 60000);
  const sign = offMin >= 0 ? '+' : '-';
  const a = Math.abs(offMin);
  return sign + pad(Math.floor(a / 60)) + ':' + pad(a % 60);
}
// Absolute ms for a wall-clock slot in the target timezone.
function slotMs(h, mi) {
  const off = offsetStr(Y, Mo, D, h, mi, tz);
  return new Date(`${targetDate}T${pad(h)}:${pad(mi)}:00${off}`).getTime();
}

// Candidate slots from APPOINTMENT_SLOTS env (comma-separated labels), else defaults.
const slotEnv = ($env.APPOINTMENT_SLOTS || '').trim();
const slotLabels = slotEnv
  ? slotEnv.split(',').map(s => s.trim()).filter(Boolean)
  : ['09:00 AM', '10:30 AM', '01:00 PM', '02:30 PM', '04:00 PM'];
const candidateSlots = slotLabels.map(label => {
  const m = label.match(/(\d{1,2}):(\d{2})\s*(AM|PM)?/i);
  let hour = 9, minute = 0;
  if (m) {
    hour = parseInt(m[1], 10); minute = parseInt(m[2], 10);
    const mer = (m[3] || '').toUpperCase();
    if (mer === 'PM' && hour < 12) hour += 12;
    if (mer === 'AM' && hour === 12) hour = 0;
  }
  return { label, hour, minute };
});

// Busy intervals from real calendar events (absolute instants).
const busy = [];
for (const item of events) {
  const evt = item.json;
  if (evt && evt.start && (evt.start.dateTime || evt.start.date)) {
    const s = new Date(evt.start.dateTime || evt.start.date).getTime();
    const endRaw = (evt.end && (evt.end.dateTime || evt.end.date)) || evt.start.dateTime || evt.start.date;
    busy.push({ start: s, end: new Date(endRaw).getTime() });
  }
}

const availableSlots = candidateSlots.filter(slot => {
  const s = slotMs(slot.hour, slot.minute);
  const e = s + 60 * 60 * 1000;
  return !busy.some(b => (s < b.end && e > b.start));
}).map(s => s.label);

const hasAvailability = availableSlots.length > 0;
let spokenSummary = '';
if (hasAvailability) {
  const slotsSpoken = availableSlots.slice(0, 4).join(', ');
  spokenSummary = `On ${targetDate}, we have availability at ${slotsSpoken}. Which of those times works best for you?`;
} else {
  spokenSummary = `We are fully booked on ${targetDate}. Would you like me to check the following business day for openings?`;
}

return {
  json: {
    date: targetDate,
    has_availability: hasAvailability,
    available_slots: availableSlots,
    timezone: tz,
    spoken_summary: spokenSummary
  }
};
